1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResult = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	
25	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
26	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
27	
28	/** The item types the MHPCO will insure, and what each costs to cover. */
29	const BASE_PREMIUMS: Record<string, number | undefined> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	/** Premium for a single item of this type. `undefined` for a type the MHPCO does not insure — rejecting those is not yet specified by a test. */
39	const unitPremiumFor = (type: string): number | undefined => BASE_PREMIUMS[type];
40	
41	/** Component types that form discounted blocks. */
42	const BLOCK_FORMING_COMPONENTS = new Set(["rune", "moonstone"]);
43	const COMPONENT_BLOCK_SIZE = 3;
44	const COMPONENT_BLOCK_PREMIUM = 60;
45	
46	const formsComponentBlock = (type: string, count: number): boolean =>
47	  BLOCK_FORMING_COMPONENTS.has(type) && count === COMPONENT_BLOCK_SIZE;
48	
49	const countByType = (items: Item[]): Map<string, number> => {
50	  const counts = new Map<string, number>();
51	  for (const item of items) {
52	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
53	  }
54	  return counts;
55	};
56	
57	/** Alike components form a discounted block; everything else is priced per unit. */
58	const basePremiumForGroup = (type: string, count: number): number => {
59	  if (formsComponentBlock(type, count)) return COMPONENT_BLOCK_PREMIUM;
60	  const unitPremium = unitPremiumFor(type);
61	  // An uninsurable type yields NaN, which propagates to the quote. Rejecting
62	  // unknown types with a real error is specified by a test we have not reached yet.
63	  return unitPremium === undefined ? NaN : count * unitPremium;
64	};
65	
66	const policyBasePremium = (items: Item[]): number =>
67	  [...countByType(items)].reduce(
68	    (total, [type, count]) => total + basePremiumForGroup(type, count),
69	    0,
70	  );
71	
72	const CURSE_SURCHARGE_RATE = 0.5;
73	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
74	const HIGH_ENCHANTMENT_THRESHOLD = 5;
75	
76	/** Item-level surcharge rates stack additively on one item. */
77	const surchargeRateFor = (item: Item): number => {
78	  const curse = item.cursed ? CURSE_SURCHARGE_RATE : 0;
79	  const highEnchantment =
80	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0;
81	  return curse + highEnchantment;
82	};
83	
84	/**
85	 * Item-level surcharges apply to the affected item's own base premium, not to
86	 * the policy total. An uninsurable type yields NaN and propagates to the quote,
87	 * as in `basePremiumForGroup`.
88	 */
89	const itemSurchargeTotal = (items: Item[]): number =>
90	  items.reduce(
91	    (total, item) => total + (unitPremiumFor(item.type) ?? NaN) * surchargeRateFor(item),
92	    0,
93	  );
94	
95	const quotePremium = (items: Item[]): number => {
96	  const policyBase = policyBasePremium(items) + itemSurchargeTotal(items);
97	  const withFirstInsurance = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
98	  const withProcessingFee = withFirstInsurance + PROCESSING_FEE;
99	  return roundUpToWholeG(withProcessingFee);
100	};
101	
102	export const runScenario = (scenario: Scenario): ScenarioResult => {
103	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
104	};
